'use strict';

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const cp = require('node:child_process');
const crypto = require('node:crypto');
const {digest} = require('./acceptance.cjs');
const {git, githubRepository, readLocalConfig, collectLocal, assertUnchanged, SourceNotFound} = require('./local-git.cjs');
const {localReview} = require('./local-review.cjs');
const {askHarness, assertHarness} = require('./local-harness.cjs');
const {issueReceipt, verifyReceipt, attestable, AUTHOR} = require('./local-receipt.cjs');
const {engineDigest} = require('./local-version.cjs');
const {SOURCE, acceptsEngine} = require('./central-version.cjs');
const {reconcile} = require('./acceptance-ledger.cjs');
const {refresh, safePath, UNBOUNDED} = require('./acceptance-sources.cjs');
const chunkedWiring = require('./chunked-wiring.cjs');
const {coverageParts} = require('./coverage-plan.cjs');
const {AGENTS, AwaitingAgent, createExchange, respond} = require('./local-agent.cjs');
const gate = require('./coverage-gate.cjs');
const pinning = require('./engine-pin.cjs');
const {createReuse} = require('./review-reuse.cjs');

const root = path.join(__dirname, '..');
// Characters of each output stream kept as review evidence; the digests always cover the whole stream.
const PASSED_OUTPUT_TAIL = 128;
const FAILED_OUTPUT_TAIL = 4096;
const stateDirectory = () => path.join(os.homedir(), '.local/share/clouseau');

function options(argv) {
  const [command, ...args] = argv;
  const parsed = {command};
  const allowed = ['directory', 'base', 'harness', 'agent', 'request-file', 'output', 'identity', 'receipt', 'additional-checks',
    'agent-request', 'answer', 'session', 'engine', 'pr'];
  for (let i = 0; i < args.length; i += 2) {
    const name = args[i].slice(2);
    if (!args[i].startsWith('--') || !allowed.includes(name) || !args[i + 1] || parsed[name]) {
      throw new Error(`Invalid Clouseau local arguments at ${JSON.stringify(args[i])}: every option is "--name value", given once; accepted: ${allowed.map(item => `--${item}`).join(' ')}`);
    }
    parsed[name] = args[i + 1];
  }
  return parsed;
}

function initializeIdentity(directory = stateDirectory(), githubActor) {
  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]{0,38}$/.test(githubActor || '')) throw new Error('An authenticated GitHub actor is required for identity enrollment');
  fs.mkdirSync(directory, {recursive: true, mode: 0o700});
  const keys = crypto.generateKeyPairSync('ed25519');
  const publicKey = keys.publicKey.export({type: 'spki', format: 'pem'});
  const id = digest(publicKey).slice(0, 24);
  const filename = path.join(directory, `${id}.json`);
  const publicIdentity = {id, issuer: `local-${id}`, github_actor: githubActor, public_key: publicKey, revoked: false};
  fs.writeFileSync(filename, JSON.stringify({...publicIdentity,
    private_key: keys.privateKey.export({type: 'pkcs8', format: 'pem'})}), {mode: 0o600, flag: 'wx'});
  return {identity_file: filename, public_identity: publicIdentity};
}

function verificationEnvironment(environment = process.env) {
  return Object.fromEntries(Object.entries(environment).filter(([name]) => !/(?:KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL)/i.test(name)));
}

function executeVerification({directory, config, additional = [], run = cp.spawnSync}) {
  const env = verificationEnvironment();
  const parts = coverageParts(config, {allowUnsupported: true});
  const commands = [];
  const directoryRoot = fs.realpathSync(directory);
  const observe = part => {
    try {
      const filename = path.join(directory, part.report);
      const resolved = fs.realpathSync(filename);
      if (!resolved.startsWith(directoryRoot + path.sep)) return {report_digest: null, error: 'Coverage artifact escapes the checkout'};
      const stat = fs.statSync(filename, {bigint: true});
      if (!stat.isFile()) return {report_digest: null, error: 'Coverage artifact is not a regular file'};
      return {report_digest: digest(fs.readFileSync(filename, 'utf8')),
        stamp: digest([stat.dev, stat.ino, stat.size, stat.mtimeNs, stat.ctimeNs].map(String))};
    } catch (error) {
      return {report_digest: null, error: error.code || 'Coverage artifact is unavailable'};
    }
  };
  const before = parts.map(observe);
  const execute = argv => {
    let result;
    try {result = run(argv[0], argv.slice(1), {cwd: directory, encoding: 'utf8', timeout: 300000, maxBuffer: 3000000, env}) || {status: null, error: new Error('Verification process returned no result')};}
    catch (error) {result = {status: null, error};}
    const stdout = result.stdout || ''; const stderr = result.stderr || '';
    // Signing material must never become model evidence, including on failure.
    if (/-----BEGIN (?:[A-Z]+ )?PRIVATE KEY-----/.test(stdout + stderr)) throw new Error('Private signing material appeared in verification output; it cannot enter review evidence');
    // The digests bind the complete output. Evidence carries its tail: a short one when the command succeeded (its
    // summary line), a longer one when it failed (its diagnosis), so a green suite's per-test lines do not cost the
    // reviewer and the receipt hundreds of kilobytes. `*_bytes` appears only where the text was cut.
    const limit = result.status === 0 && !result.error && !result.signal ? PASSED_OUTPUT_TAIL : FAILED_OUTPUT_TAIL;
    // A tail never starts inside a surrogate pair, so it may be one unit shorter than the limit.
    const tail = (text, name) => text.length <= limit ? {[name]: text} :
      {[name]: text.slice(-limit).replace(/^[\uDC00-\uDFFF]/, ''), [`${name}_bytes`]: Buffer.byteLength(text)};
    commands.push({argv, exit_code: Number.isInteger(result.status) ? result.status : null,
      stdout_digest: digest(stdout), stderr_digest: digest(stderr), ...tail(stdout, 'stdout'), ...tail(stderr, 'stderr'),
      ...(result.error ? {error: {code: result.error.code || null, message: result.error.message}} : {}),
      ...(result.signal ? {signal: result.signal} : {})});
  };
  for (const argv of config.verification) execute(argv);
  const observed = parts.map(observe);
  const reports = parts.map((part, index) => ({...part, report_digest: observed[index].report_digest}));
  const fresh = observed.every((part, index) => !part.error && part.stamp !== before[index].stamp);
  let measured = null;
  let coverageError = observed.find(part => part.error)?.error;
  if (!coverageError) {
    try {
      measured = config.version === 1 ?
        gate.measure(gate.readReport(parts[0].format, path.join(directory, parts[0].report)), path.join(directory, parts[0].source_directory), parts[0].format, directory) :
        gate.measurePlan(parts, directory);
    } catch (error) {coverageError = error.message || 'Native coverage could not be measured';}
  }
  for (const argv of additional) execute(argv);
  if (additional.length && observed.some((part, index) => digest(part) !== digest(observe(parts[index])))) {
    throw new Error('Additional checks changed accepted coverage artifacts');
  }
  const counts = measured && (config.version === 1 ? measured : measured.totals);
  const exact = counts && counts.lines[0] > 0 && ['lines', 'branches'].every(metric => counts[metric][0] === counts[metric][1]);
  const verification = {commands, verification_status: commands.every(command => command.exit_code === 0 && !command.error) ? 'passed' : 'failed',
    exact_coverage: counts, coverage: {status: coverageError ? 'unavailable' : exact ? 'exact' : 'below_threshold',
      passed: Boolean(exact && fresh), artifact_freshness: fresh ? 'observed_current_run' : 'unverified',
      ...(coverageError ? {error: coverageError} : {})}, local_config_digest: digest(config)};
  if (config.version === 1) return {...verification, report_digest: reports[0].report_digest};
  return {...verification, coverage_reports: reports.map((part, index) => ({...part,
    exact_coverage: measured ? measured.parts[index].counts : null})), report_digest: digest(reports)};
}

function reviewStatus(technical = {}) {
  return {decision_scope: 'review_reuse_only', independent_ci_required: true, merge_authority: false,
    local_verification: {commands: technical.verification_status || 'unavailable', coverage: technical.coverage || {status: 'unavailable', passed: false}}};
}

function installation() {
  return {sha: git(root, ['rev-parse', 'HEAD']).trim(), digest: engineDigest(), clean: !git(root, ['status', '--porcelain']).trim()};
}

function readHistory(filename, repository, branch) {
  if (!fs.existsSync(filename)) return null;
  const text = fs.readFileSync(filename, 'utf8');
  if (text.length > 250000) throw new Error('Local finding history exceeds its evidence budget');
  const value = JSON.parse(text);
  if (value.version !== 1 || value.repository !== repository || value.branch !== branch ||
    !/^[a-f0-9]{40}$/.test(value.head_sha) || !/^[a-f0-9]{40}$/.test(value.base_sha) ||
    (value.reviewer_sha !== undefined && !/^[a-f0-9]{40}$/.test(value.reviewer_sha)) ||
    !/^[a-f0-9]{64}$/.test(value.reviewer_digest) || !/^[a-f0-9]{64}$/.test(value.request_digest) ||
    !/^[a-f0-9]{64}$/.test(value.cache_id) || typeof value.has_receipt !== 'boolean' ||
    !['auto_approve', 'repair_required', 'review_incomplete', 'owner_decision', 'blocked_integrity'].includes(value.decision) ||
    !Array.isArray(value.findings) || value.findings.some(item =>
      !/^[a-f0-9]{64}$/.test(item.id) || typeof item.blocking !== 'boolean' || !safePath(item.path) ||
      !['title', 'cause', 'obligation'].every(key => typeof item[key] === 'string' && item[key].length > 0 && item[key].length <= 2000))) {
    throw new Error('Invalid local finding history; preserve it and investigate before reviewing');
  }
  return value;
}

// The live facts about someone else's pull request that a maintainer attestation is bound to. GitHub, not the checkout,
// says who the author is; the checked-out HEAD must be exactly the pull request head the author published.
function readPull({repo, number, base, head, execute}) {
  const pull = JSON.parse(execute('gh', ['api', `repos/${repo.owner}/${repo.repo}/pulls/${number}`, '--jq',
    '{author: .user.login, head: .head.sha, base: .base.ref, state: .state}'], {encoding: 'utf8'}));
  if (pull.state !== 'open' || pull.base !== base) throw new Error(`Pull request ${number} is not open against ${base}`);
  if (typeof pull.author !== 'string' || !AUTHOR.test(pull.author)) throw new Error(`Pull request ${number} has no usable author login`);
  if (pull.head !== head) {
    throw new Error(`Local HEAD ${head} is not the head of pull request ${number} (${pull.head}); check out exactly that commit ` +
      `(for a fork: git fetch origin refs/pull/${number}/head && git checkout --detach FETCH_HEAD) and review again`);
  }
  return {author: pull.author, number: Number(number)};
}

async function runReview(args, {ask = askHarness, execute = cp.execFileSync, verify = executeVerification, state = stateDirectory(), installed = installation,
  cacheRoot = path.dirname(path.dirname(root)), run = pinning.execute, reuse = {}} = {}) {
  const directory = path.resolve(args.directory || process.cwd());
  if (!args['request-file']) throw new Error('An explicit requirement file is required');
  const agent = args.agent;
  if (agent && args.harness) throw new Error('Choose either --agent (inside an AI harness) or --harness (headless), not both');
  if (agent && !AGENTS.includes(agent)) throw new Error(`Supported agent harnesses: ${AGENTS.join(', ')}`);
  if (args.harness) assertHarness(args.harness);
  const base =args.base || `origin/${readLocalConfig(JSON.parse(git(directory, ['show', 'HEAD:.clouseau-local.json']))).base_branch}`;
  const config = readLocalConfig(JSON.parse(git(directory, ['show', `${base}:.clouseau-local.json`])));
  const head = git(directory, ['rev-parse', 'HEAD']).trim();
  const repo = githubRepository(directory);
  const repository = `${repo.owner}/${repo.repo}`;
  if (git(directory, ['status', '--porcelain']).trim()) throw new Error('Commit the complete change before local review');
  const reviewer = installed();
  const reviewerSha = reviewer.sha;
  const engine = {...SOURCE, sha: reviewer.sha, digest: reviewer.digest};
  const request = fs.readFileSync(args['request-file'], 'utf8');
  if (!request.trim() || request.length > 20000) throw new Error('A bounded, nonempty requirement is required');
  const additionalText = args['additional-checks'] ? fs.readFileSync(args['additional-checks'], 'utf8') : '[]';
  if (additionalText.length > 8000) throw new Error('Additional local checks exceed the input budget');
  const additional = JSON.parse(additionalText);
  if (!Array.isArray(additional) || additional.length > 8) throw new Error('Additional local checks require at most eight argument arrays');
  if (additional.length) readLocalConfig({...config, verification: additional});
  const requestDigest = additional.length ? digest({request, additional}) : digest(request);
  let ciConfig = null;
  if (git(directory, ['ls-tree', base, '--', '.github/clouseau.json']).trim()) {
    const parsed = JSON.parse(git(directory, ['show', `${base}:.github/clouseau.json`]));
    ciConfig = require('./config.cjs').validateConfig(parsed);
  }
  const warn = (paths, shas) => {const warnings = controlWarnings(ciConfig, paths, {directory, ...shas}); return warnings.length ? {warnings} : {};};
  let identityPath = args.identity;
  if (!identityPath && ciConfig?.local_review) {
    const available = ciConfig.local_review.keys.filter(key => !key.revoked)
      .map(key => path.join(state, `${key.id}.json`)).filter(filename => fs.existsSync(filename));
    if (available.length > 1) throw new Error('Multiple enrolled identities are installed; select one explicitly');
    identityPath = available[0];
  }
  // Opt-in maintainer attestation of another author's pull request (docs/local-review.md). Without --pr nothing changes.
  let pull = null;
  if (args.pr !== undefined) {
    if (!/^[1-9][0-9]{0,8}$/.test(args.pr)) throw new Error('--pr takes a pull request number');
    if (!ciConfig?.local_review?.attest) throw new Error('Maintainer attestation is not enabled: the protected CI configuration needs local_review.attest');
    if (!identityPath) throw new Error('Attesting a pull request needs an enrolled signing identity');
    pull = readPull({repo, number: args.pr, base: config.base_branch, head, execute});
  }
  if (identityPath && !reviewer.clean) throw new Error('Signing requires an unmodified Clouseau checkout');
  const baseSha = git(directory, ['rev-parse', base]).trim();
  const branch = pull ? `pull/${pull.number}` : git(directory, ['rev-parse', '--abbrev-ref', 'HEAD']).trim();
  // An in-flight agent review stays on the engine revision that began it until it completes or --engine latest is given.
  if (args.engine && args.engine !== 'latest') throw new Error('--engine accepts only "latest"');
  const pinId = pinning.pinKey({repository, head, baseSha, requestDigest, agent: agent || null, ...(pull ? {pr: pull.number} : {})});
  if (args.engine === 'latest') pinning.clearPin(state, pinId);
  const pin = pinning.readPin(state, pinId);
  if (pin && pin.reviewer_sha !== reviewer.sha) {
    const checkout = pinning.verifiedRevision(cacheRoot, pin);
    process.stderr.write(`Clouseau review pinned to engine ${pin.reviewer_sha.slice(0, 12)}; newer ${reviewer.sha.slice(0, 12)} exists (pass --engine latest to restart on it)\n`);
    return run(checkout, pinning.argvFor(args));
  }
  const historyPath = path.join(state, 'ledgers', `${digest({repository, branch})}.json`);
  const previous = readHistory(historyPath, repository, branch);
  const priorFindings = previous?.findings || [];
  const sameRevision = previous && previous.head_sha === head && previous.base_sha === baseSha && previous.reviewer_digest === reviewer.digest;
  if (sameRevision && previous.decision !== 'auto_approve') {
    throw new Error('This revision already has a non-passing local review; repair the implementation or trusted evidence before reassessing');
  }
  let cacheId = digest({repository, head, base: baseSha, reviewerSha, reviewerDigest: reviewer.digest,
    request, config, ciConfig, harness: agent ? `agent:${agent}` : args.harness || 'codex', priorFindings, ...(additional.length ? {additional} : {}), ...(pull ? {attest: pull} : {})});
  if (sameRevision && previous.reviewer_sha === reviewerSha && previous.request_digest === requestDigest) cacheId = previous.cache_id;
  const cache = path.join(state, 'reviews', cacheId);
  const journal = path.join(cache, 'observations.jsonl');
  const cachedReceipt = path.join(cache, 'receipt.json');
  if (ciConfig?.local_review && fs.existsSync(cachedReceipt)) {
    const bundle = JSON.parse(fs.readFileSync(cachedReceipt, 'utf8'));
    const key = ciConfig.local_review.keys.find(item => item.id === bundle.payload.key_id);
    const verified = verifyReceipt(bundle, {engine, trust: ciConfig.local_review, repository,
      author: pull ? pull.author : key?.github_actor, pullNumber: pull?.number, headSha: head, baseSha: git(directory, ['rev-parse', base]).trim(),
      reviewerDigest: reviewer.digest, configDigest: digest(ciConfig),
      policyDigest: digest(fs.readFileSync(path.join(root, 'policy/change-acceptance.md'), 'utf8'))});
    assertUnchanged(directory, verified.record.snapshot);
    return {decision: 'auto_approve', record: path.join(cache, 'record.json'), receipt: cachedReceipt,
      head_sha: head, base_sha: verified.record.snapshot.base_sha, reviewer_sha: bundle.payload.reviewer_sha,
      provider_api_calls: 0, harness_invocations: 0, reused: true, ...attested(verified.attestation), ...reviewStatus(verified.record.technical), ...warn(verified.record.snapshot.paths, {baseSha: verified.record.snapshot.base_sha, headSha: head})};
  }
  const agentDirectory = path.join(cache, 'agent');
  // An unfinished agent exchange resumes from its recorded evidence; any other prior journal means the input already ran.
  // A chunked review keeps its own durable journal and verification record, so it resumes without resampling a finished call.
  const chunkedDirectory = path.join(cache, 'chunked');
  const chunkedResume = fs.existsSync(path.join(chunkedDirectory, 'technical.json'));
  const resuming = (Boolean(agent) && fs.existsSync(path.join(agentDirectory, 'technical.json')) &&
    !fs.existsSync(path.join(agentDirectory, 'completed.json'))) || chunkedResume;
  if (fs.existsSync(journal) && !resuming) throw new Error(`This exact review input has already run; inspect ${cache}. Change the implementation or evidence before another AI review.`);
  const output = path.resolve(args.output || path.join(cache, 'record.json'));
  if (output.startsWith(directory + path.sep)) throw new Error('Store review evidence outside the source checkout');
  let identity = null; let attestation;
  if (identityPath) {
    if (fs.statSync(identityPath).mode & 0o077) throw new Error('Signing identity permissions must be private');
    identity = JSON.parse(fs.readFileSync(identityPath, 'utf8'));
    if (!ciConfig?.local_review || !acceptsEngine(ciConfig.local_review, engine) ||
      !ciConfig.local_review.keys.some(key => !key.revoked && key.id === identity.id &&
        key.issuer === identity.issuer && key.github_actor === identity.github_actor && key.public_key === identity.public_key)) {
      throw new Error('The signer and reviewer revision must already be enrolled in the protected CI configuration');
    }
    if (pull && pull.author !== identity.github_actor) {
      if (!attestable(ciConfig.local_review, pull.author)) {
        throw new Error(`Pull request author ${pull.author} is not permitted by the protected local_review.attest configuration`);
      }
      attestation = {author: pull.author, number: pull.number, signer: identity.github_actor};
    }
  }
  const technicalPath = path.join(agentDirectory, 'technical.json');
  let technical;
  if (chunkedResume && !agent) technical = JSON.parse(fs.readFileSync(path.join(chunkedDirectory, 'technical.json'), 'utf8'));
  else if (resuming) technical = JSON.parse(fs.readFileSync(technicalPath, 'utf8'));
  else {
    technical = verify({directory, config, additional});
    if (agent) {
      // The agent exchange spans several commands; persist the one real verification so later commands cannot rerun it.
      technical = JSON.parse(JSON.stringify(technical));
      fs.mkdirSync(agentDirectory, {recursive: true, mode: 0o700});
      fs.writeFileSync(technicalPath, JSON.stringify(technical), {mode: 0o600});
    }
  }
  if (git(directory, ['rev-parse', 'HEAD']).trim() !== head) throw new Error('Source changed during local verification');
  // Chunked review is available by default; the protected configuration can only tighten or disable it. A change that fits one
  // snapshot is collected and reviewed exactly as before. One that does not (or that the configuration forces) is collected
  // without a size cap and reviewed in bounded units.
  const active = chunkedWiring.settings(ciConfig?.local_review);
  const collect = unbounded => collectLocal({directory, base, request, technical, ciConfig, reviewerSha, unbounded});
  let collected; let chunking = false;
  if (active?.force) {collected = collect(true); chunking = true;}
  else {
    try {collected = collect(false);} catch (error) {
      if (!active) throw error;
      collected = collect(true); chunking = true;
    }
  }
  collected.snapshot.prior_findings = priorFindings;
  refresh(collected.snapshot, chunking ? UNBOUNDED : undefined);
  if (chunking && !agent) {
    fs.mkdirSync(chunkedDirectory, {recursive: true, mode: 0o700});
    fs.writeFileSync(path.join(chunkedDirectory, 'technical.json'), JSON.stringify(technical), {mode: 0o600});
  }
  fs.mkdirSync(cache, {recursive: true, mode: 0o700});
  if (agent) {
    pinning.writePin(state, pinId, reviewer);
    const frozen = path.join(agentDirectory, 'snapshot.digest');
    if (!fs.existsSync(frozen)) fs.writeFileSync(frozen, collected.snapshot.digest, {mode: 0o600});
    else if (fs.readFileSync(frozen, 'utf8') !== collected.snapshot.digest) {
      throw new Error(`Source or evidence changed since this agent exchange began; evidence preserved in ${agentDirectory}`);
    }
  }
  const exchange = agent ? createExchange({directory: agentDirectory, agent,
    journal: entry => fs.appendFileSync(journal, JSON.stringify(entry) + '\n', {mode: 0o600})}) : null;
  const session = async task => {
    if (exchange) return exchange.ask(task);
    fs.appendFileSync(journal, JSON.stringify({role: task.role, phase: task.phase, status: 'started',
      request_digest: digest(task)}) + '\n', {mode: 0o600});
    const response = await ask({...task, harness: args.harness || 'codex'});
    fs.appendFileSync(journal, JSON.stringify({role: task.role, phase: task.phase, ...response}) + '\n', {mode: 0o600});
    return response;
  };
  // Every call of this review is remembered by its evidence once the review is accepted; `reuse.read` (the refresh command)
  // lets a call whose evidence is byte-identical to a remembered one take that answer instead of asking again.
  let unitDigests = null;
  const reusing = createReuse({directory: path.join(state, 'unit-reuse'), read: reuse.read === true,
    semantics: require('./review-semantics.cjs').semanticsDigest(), literals: () => {
      if (chunking && !unitDigests) {
        unitDigests = chunkedWiring.hooksFor(active.params).partition({snapshot: collected.snapshot}).units.map(unit => unit.view_digest);
      }
      return {base: baseSha, head, digests: [collected.snapshot.digest, ...(unitDigests || [])]};
    }});
  const asking = reusing.wrap(session);
  let result; let chunkedRecord = null; let reviews;
  try {
    if (chunking) {
      fs.writeFileSync(path.join(cache, 'snapshot.json'), JSON.stringify(collected.snapshot) + '\n', {mode: 0o600});
      ({record: chunkedRecord, reviews} = await chunkedWiring.review({snapshot: collected.snapshot, active, ask: asking, agent: Boolean(agent),
        journal: exchange ? undefined : chunkedWiring.fileJournal(path.join(chunkedDirectory, 'journal')), scope: cacheId,
        technical, priorFindings}));
      result = chunkedRecord.result;
    } else {
      result = await localReview({...collected, ask: async task => {
        fs.writeFileSync(path.join(cache, 'snapshot.json'), JSON.stringify(collected.snapshot) + '\n', {mode: 0o600});
        return asking(task);
      }});
    }
  } catch (error) {
    if (error instanceof AwaitingAgent) {
      return {status: 'awaiting_agent', ...error.info, reviewer_sha: reviewerSha, provider_api_calls: 0, harness_invocations: 0,
        respond: `clouseau respond --agent-request ${error.info.request_file} --answer ${error.info.answer_file} --session FRESH_SESSION_ID`,
        then: 'Repeat the identical review command. It continues on this pinned engine revision even if Clouseau main advances; pass --engine latest to restart on the newest.'};
    }
    if (error instanceof SourceNotFound) {
      const failed = {status: 'failed', reason: error.reason, path: error.path};
      fs.writeFileSync(path.join(cache, 'failure.json'), JSON.stringify({...failed, failure: error.message, harness: null}, null, 2) + '\n', {mode: 0o600});
      return {...failed, evidence: cache};
    }
    fs.writeFileSync(path.join(cache, 'failure.json'), JSON.stringify({failure: error.message,
      harness: error.harnessDiagnostic || null}, null, 2) + '\n', {mode: 0o600});
    error.message += `; preserved review evidence: ${cache}`; throw error;
  }
  if (agent) {
    fs.writeFileSync(path.join(agentDirectory, 'completed.json'), '{}\n', {mode: 0o600});
    pinning.clearPin(state, pinId);
  }
  assertUnchanged(directory, collected.snapshot);
  const findings = reconcile(chunking ? {...result, reviews} : result, collected.snapshot, priorFindings);
  if (findings.unresolved.length && result.decision === 'auto_approve') result.decision = 'review_incomplete';
  reusing.commit(result.decision);
  const record = chunkedRecord || {version: 2, snapshot: collected.snapshot, result, previous: {comment: null, findings: []},
    local_previous: {findings: priorFindings}, controls: false, technical};
  fs.mkdirSync(path.dirname(output), {recursive: true});
  fs.writeFileSync(output, JSON.stringify(record) + '\n', {mode: 0o600});
  let receipt = null;
  if (result.decision === 'auto_approve' && identity) {
    if (digest(installed()) !== digest(reviewer)) throw new Error('Clouseau installation changed during review; no receipt issued');
    const bundle = issueReceipt({record, privateKey: identity.private_key, keyId: identity.id,
      issuer: identity.issuer, reviewerSha, reviewerDigest: reviewer.digest,
      reviewerSemantics: require('./review-semantics.cjs').semanticsDigest(),
      lifetime: ciConfig.local_review.max_age_seconds, attestation, chunked: chunking ? chunkedWiring.verifierOptions(ciConfig.local_review) : null});
    verifyReceipt(bundle, {engine, trust: ciConfig.local_review, repository: collected.snapshot.repository, author: pull ? pull.author : identity.github_actor, pullNumber: pull?.number,
      headSha: head, baseSha: collected.snapshot.base_sha, reviewerSha, reviewerDigest: reviewer.digest,
      configDigest: collected.snapshot.config_digest, policyDigest: collected.snapshot.policy_digest});
    receipt = path.join(cache, 'receipt.json');
    fs.writeFileSync(receipt, JSON.stringify(bundle) + '\n', {mode: 0o600});
  }
  fs.mkdirSync(path.dirname(historyPath), {recursive: true, mode: 0o700});
  fs.writeFileSync(historyPath, JSON.stringify({version: 1, repository, branch, head_sha: head, base_sha: baseSha,
    reviewer_sha: reviewerSha, reviewer_digest: reviewer.digest, request_digest: requestDigest, cache_id: cacheId,
    has_receipt: Boolean(receipt), decision: result.decision, findings: findings.findings}), {mode: 0o600});
  return {decision: result.decision, record: output, receipt, head_sha: head,
    base_sha: collected.snapshot.base_sha, reviewer_sha: reviewerSha, provider_api_calls: 0, ...attested(attestation),
    harness_invocations: result.usage.length - reusing.stats.reused, reused_calls: reusing.stats.reused, ...reviewStatus(technical), ...warn(collected.snapshot.paths, {baseSha: collected.snapshot.base_sha, headSha: head})};
}

const attested = attestation => attestation ? {maintainer_attested: {author: attestation.author, pull_request: attestation.number}} : {};

// A receipt that touches protected review controls verifies but cannot carry owner confirmation, so CI holds the review.
// Say so while the author can still act, naming only repository paths.
function controlWarnings(config, paths, {directory, baseSha, headSha}) {
  const protectedHits = config ? require('./policy.cjs').protectedChanges(config, paths.map(filename => ({filename}))) : [];
  // The opt-in managed-standard update is judged on the same base and head bytes CI reads (managed-agents.cjs).
  const hits = protectedHits.filter(name => !(name === 'AGENTS.md' && config.managed_agents && managedUpdate(config, directory, baseSha, headSha)));
  if (!hits.length) return [];
  const warning = `Protected review controls changed (${hits.slice(0, 5).join(', ')}): CI cannot accept a local receipt for this change ` +
    'without the exact-head owner confirmation (/approve-intent) and will report review_incomplete. Keep such files (for example the AGENTS.md managed-rules update) out of this pull request, or ask a maintainer to confirm the exact head.';
  process.stderr.write(`warning: ${warning}\n`);
  return [warning];
}

function managedUpdate(config, directory, baseSha, headSha) {
  const read = ref => {try {return git(directory, ['show', `${ref}:AGENTS.md`]);} catch {return null;}};
  const baseText = read(baseSha);
  const headText = read(headSha);
  return baseText !== null && headText !== null &&
    require('./managed-agents.cjs').judge({baseText, headText, digests: config.managed_agents.digests}).exempt;
}

function publishReceipt({directory, receipt}) {
  const bundle = JSON.parse(fs.readFileSync(receipt, 'utf8'));
  const {parts = [], ...envelope} = bundle;
  const {payload} = envelope;
  // A multi-part receipt (receipt-parts.cjs) publishes its signed envelope and every part as files of the one commit.
  const {isRoot, joinRecord, partName} = require('./receipt-parts.cjs');
  const record = isRoot(payload.record) ? joinRecord(payload.record, parts.map(part => Buffer.from(part, 'base64'))) : payload.record;
  assertUnchanged(directory, record.snapshot);
  const configured = git(directory, ['ls-tree', record.snapshot.base_sha, '--', '.github/clouseau.json']).trim();
  const warnings = controlWarnings(configured ? require('./config.cjs').validateConfig(JSON.parse(
    git(directory, ['show', `${record.snapshot.base_sha}:.github/clouseau.json`]))) : null, record.snapshot.paths,
  {directory, baseSha: record.snapshot.base_sha, headSha: record.snapshot.head_sha});
  const files = [['clouseau-review.json', JSON.stringify(envelope) + '\n'],
    ...parts.map((part, index) => [partName(index), Buffer.from(part, 'base64')])];
  const entries = files.map(([name, content]) => `100644 blob ${git(directory, ['hash-object', '-w', '--stdin'], content).trim()}\t${name}\n`);
  const tree = git(directory, ['mktree'], entries.join('')).trim();
  const commit = git(directory, ['-c', 'user.name=Clouseau', '-c', 'user.email=clouseau@localhost', 'commit-tree', tree],
    `Authenticated local review of ${record.snapshot.head_sha}\n`).trim();
  git(directory, ['push', 'origin', `${commit}:refs/tags/clouseau-review/${payload.nonce}`]);
  return {artifact_commit: commit, ...attested(payload.attestation), marker: `<!-- clouseau-local-review:v1 ${commit} -->`, ...(warnings.length ? {warnings} : {})};
}

async function main(argv, runtime = {}) {
  if (['--help', '-h', 'help'].includes(argv[0])) return require('./cli-usage.cjs').usage();
  if (argv[0] === 'public-identity' || argv[0]?.startsWith('installation-')) return require('./installation-cli.cjs').main(argv, runtime);
  const args = options(argv);
  if (args.command === 'init-identity') return initializeIdentity(runtime.identityDirectory,
    (runtime.execute || cp.execFileSync)('gh', ['api', 'user', '--jq', '.login'], {encoding: 'utf8'}).trim());
  if (args.command === 'review') return runReview(args, runtime);
  if (args.command === 'refresh') {
    return require('./pr-refresh.cjs').refreshPull(args, {review: reviewArgs => runReview(reviewArgs, {...runtime, reuse: {read: true}}),
      publish: publishReceipt, execute: runtime.execute, available: runtime.available});
  }
  if (args.command === 'respond') return respond({request: args['agent-request'], answer: args.answer, session: args.session});
  if (args.command === 'publish' && args.directory && args.receipt) return publishReceipt(args);
  throw new Error(require('./cli-usage.cjs').usage());
}

module.exports = {options, stateDirectory, initializeIdentity, verificationEnvironment, executeVerification, reviewStatus, installation, readHistory, runReview, publishReceipt, controlWarnings, main};

'use strict';

// `clouseau refresh --pr N`: bring one open pull request of this repository up to its moved base and give it fresh review
// evidence, with one push (docs/local-review.md, "Refreshing a pull request after its base moved").
//
// The steps are the author's manual routine, in this order and no other: fetch the base, merge it (never a rebase), review
// the new head locally, publish the receipt, put its marker in the pull request body, push the branch once, last. The
// review reuses the answers of an earlier accepted review for every call whose evidence is byte-identical (review-reuse.cjs);
// everything else is asked again. Nothing here decides or signs anything: the review, receipt and publication are the
// ordinary ones, passed in as `review` and `publish`.
//
// Every refusal happens before anything is pushed, and several before anything is changed at all: a dirty worktree, a head
// that is not the pull request head, a pull request of another repository or branch, a missing harness and a merge conflict
// leave the checkout exactly as it was. A review that does not pass, or a passing one without a signed receipt, leaves the
// merge commit in the local branch and pushes nothing.

const path = require('node:path');
const cp = require('node:child_process');
const {git, githubRepository, readLocalConfig, assertUnchanged} = require('./local-git.cjs');
const {AGENTS} = require('./local-agent.cjs');
const {assertHarness} = require('./local-harness.cjs');

const MARKER = /<!-- clouseau-local-review:v1 [a-f0-9]{40} -->/;

const first = error => String(error.stderr).trim().split('\n')[0];

function ancestor(directory, candidate, descendant) {
  try {
    git(directory, ['merge-base', '--is-ancestor', candidate, descendant]);
    return true;
  } catch {
    return false;
  }
}

// The pull request body with exactly one marker, the new one: where the old marker was, else at the end.
function withMarker(body, marker) {
  if (!MARKER.test(body)) return `${body.replace(/\s+$/, '')}${body.trim() ? '\n\n' : ''}${marker}\n`;
  const global = new RegExp(MARKER.source, 'g');
  let seen = false;
  return body.replace(global, () => {
    if (seen) return '';
    seen = true;
    return marker;
  });
}

// Whether HEAD is the merge commit an interrupted refresh made: the pull request head and a commit of the base.
function resumable({directory, head, pullHead, remoteBase}) {
  const parents = git(directory, ['rev-list', '--parents', '-n', '1', head]).trim().split(' ');
  return parents.length === 3 && parents[1] === pullHead && ancestor(directory, parents[2], remoteBase);
}

function merge({directory, remoteBase, branch}) {
  try {
    git(directory, ['merge-tree', '--write-tree', '--name-only', 'HEAD', remoteBase]);
  } catch (error) {
    // After a conflict git prints the tree id, one conflicted path per line, a blank line, then its messages.
    const conflicted = String(error.stdout).split('\n').slice(1).join('\n').split('\n\n')[0].split('\n').filter(Boolean);
    const cause = conflicted.length ? `conflicts in ${conflicted.join(', ')}` : first(error);
    throw new Error(`${remoteBase} cannot be merged cleanly (${cause}). Nothing was changed; merge the base yourself, resolve it and review again.`);
  }
  try {
    git(directory, ['merge', '--no-ff', '--no-edit', '-m', `Merge ${remoteBase} into ${branch}`, remoteBase]);
  } catch (error) {
    // The merge cannot conflict (checked above); this is a hook or an environment refusing it. Leave no half-made merge.
    cp.spawnSync('git', ['-C', directory, 'merge', '--abort'], {stdio: 'ignore'});
    throw new Error(`Merging ${remoteBase} failed (${first(error)}); the branch is unchanged and nothing was pushed`);
  }
}

async function refreshPull(args, {review, publish, execute = cp.execFileSync, available = name => cp.spawnSync(name, ['--version'], {stdio: 'ignore'}).status === 0}) {
  if (!/^[1-9][0-9]{0,8}$/.test(args.pr || '')) throw new Error('--pr takes a pull request number');
  if (!args['request-file']) throw new Error('An explicit requirement file is required: pass the file the earlier review used, because reuse needs byte-identical input');
  if (Boolean(args.agent) === Boolean(args.harness)) throw new Error('Choose exactly one of --agent (inside an AI harness) or --harness (headless)');
  if (args.agent && !AGENTS.includes(args.agent)) throw new Error(`Supported agent harnesses: ${AGENTS.join(', ')}`);
  if (args.harness) {
    assertHarness(args.harness);
    if (!available(args.harness)) throw new Error(`The ${args.harness} harness is not installed or not on PATH; nothing was changed`);
  }
  const number = Number(args.pr);
  const directory = path.resolve(args.directory || process.cwd());
  const repo = githubRepository(directory);
  const slug = `${repo.owner}/${repo.repo}`;
  if (git(directory, ['status', '--porcelain']).trim()) {
    throw new Error('Refusing to refresh a worktree with uncommitted or untracked changes; commit or stash them first');
  }
  const branch = git(directory, ['rev-parse', '--abbrev-ref', 'HEAD']).trim();
  const readPull = () => JSON.parse(execute('gh', ['api', `repos/${slug}/pulls/${number}`, '--jq',
    '{state: .state, base: .base.ref, head: .head.sha, ref: .head.ref, repository: .head.repo.full_name, body: (.body // "")}'], {encoding: 'utf8'}));
  const pull = readPull();
  if (pull.state !== 'open') throw new Error(`Pull request ${number} is not open`);
  if (pull.repository !== slug) throw new Error(`Pull request ${number} comes from ${pull.repository}; refresh pushes only to a branch of ${slug}`);
  if (branch !== pull.ref) throw new Error(`The checked-out branch ${branch} is not the pull request branch ${pull.ref}`);
  const config = readLocalConfig(JSON.parse(git(directory, ['show', 'HEAD:.clouseau-local.json'])));
  if (pull.base !== config.base_branch) throw new Error(`Pull request ${number} is against ${pull.base}, not the configured base ${config.base_branch}`);
  const remoteBase = `origin/${pull.base}`;
  const head = git(directory, ['rev-parse', 'HEAD']).trim();
  const resuming = head !== pull.head;
  if (resuming && !resumable({directory, head, pullHead: pull.head, remoteBase})) {
    throw new Error(`Local HEAD ${head} is not the head of pull request ${number} (${pull.head}); check out exactly that commit and refresh again`);
  }
  // A refresh interrupted after its merge (an agent-driven review awaiting an answer) continues on the base it began with.
  if (!resuming) {
    git(directory, ['fetch', 'origin', `+refs/heads/${pull.base}:refs/remotes/${remoteBase}`]);
    if (ancestor(directory, remoteBase, 'HEAD')) {
      return {status: 'up_to_date', pull_request: number, head_sha: head, base_sha: git(directory, ['rev-parse', remoteBase]).trim(), pushed: false,
        note: `Pull request ${number} already contains ${remoteBase}; nothing to refresh`};
    }
    merge({directory, remoteBase, branch});
  }
  const result = await review({directory, base: remoteBase, 'request-file': args['request-file'], harness: args.harness, agent: args.agent,
    identity: args.identity, 'additional-checks': args['additional-checks'], engine: args.engine});
  const context = {pull_request: number, previous_head_sha: pull.head, pushed: false};
  if (result.status === 'awaiting_agent') {
    return {...result, ...context, then: 'Repeat the identical refresh command. It continues on the merge commit already made and on this pinned engine revision.'};
  }
  if (result.status) return {...result, ...context};
  if (result.decision !== 'auto_approve') return {...result, ...context, note: 'The review did not pass; nothing was pushed. The merge commit remains in the local branch.'};
  if (!result.receipt) {
    throw new Error('The review passed but produced no signed receipt (no enrolled signing identity was selected); nothing was pushed. Enroll or pass --identity and refresh again');
  }
  assertUnchanged(directory, {head_sha: result.head_sha});
  const published = await publish({directory, receipt: result.receipt});
  const live = readPull();
  if (live.state !== 'open' || live.head !== pull.head) {
    throw new Error(`Pull request ${number} changed during the refresh (head ${live.head}, expected ${pull.head}); nothing was pushed`);
  }
  const body = withMarker(live.body, published.marker);
  const patch = text => execute('gh', ['api', '-X', 'PATCH', `repos/${slug}/pulls/${number}`, '--input', '-'], {encoding: 'utf8', input: JSON.stringify({body: text})});
  // The marker goes into the body before the push, as the pull request is read on the push; the push is the last step.
  patch(body);
  try {
    git(directory, ['push', 'origin', `HEAD:refs/heads/${pull.ref}`]);
  } catch (error) {
    patch(live.body);
    throw new Error(`The push failed (${first(error)}); the pull request body was restored and the branch on GitHub is unchanged`);
  }
  return {...result, ...context, status: 'refreshed', pushed: true, marker: published.marker, artifact_commit: published.artifact_commit,
    ...(published.warnings ? {warnings: published.warnings} : {})};
}

module.exports = {refreshPull, withMarker, merge, resumable};

'use strict';
const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {git} = require('./local-git.cjs');
const {digest} = require('./acceptance.cjs');
const {initializeIdentity, main} = require('./local-cli.cjs');
const {refreshPull, withMarker} = require('./pr-refresh.cjs');

const GITHUB = 'git@github.com:example/local-fixture.git';
const MARKER = sha => `<!-- clouseau-local-review:v1 ${sha} -->`;
const installed = () => ({sha: 'e'.repeat(40), digest: 'e'.repeat(64), clean: true});

function fakeHarness(calls) {
  let count = 0;
  return async task => {
    calls.push(`${task.role}:${task.phase}`);
    let value;
    if (task.phase === 'investigation') {
      const report = JSON.parse(task.prompt.slice(task.prompt.lastIndexOf('\n') + 1)).template;
      report.gates.forEach(gate => {gate.state = 'satisfied';});
      value = {kind: 'report', report, request_sources: []};
    } else if (task.phase === 'integration') {
      value = {dispositions: JSON.parse(task.prompt.slice(task.prompt.lastIndexOf('\n') + 1)).seams.map(seam => ({seam: seam.id, state: 'checked', reason: 'Both ends hold.'}))};
    } else value = {answers: Object.fromEntries(Object.keys(task.schema.properties.answers.properties).map(id => [id, id.includes('_excess_') ? 'level0' : 'level4']))};
    return {value, provenance: {harness: 'claude', role: task.role, phase: task.phase, session: `fictional-session-${++count}`,
      request_digest: digest(task), response_digest: digest(value), transport_digest: digest({fixture_only: value})}};
  };
}

// Five lines: the pull request edits the third, the base may edit the fifth, and the fourth keeps the two apart.
const handler = (body, tail) => `// Handler.\nconst MARK = 1;\nmodule.exports = input => ${body};\nconst END = 2;\n// tail: ${tail}\n`;

// A pull request fixture: a bare "GitHub" origin, a working clone on the feature branch, and a second clone that moves main.
async function pullRepository(run, {ciConfig = null, files = {}} = {}) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-refresh-'));
  try {
    const bare = path.join(root, 'origin.git'); git(root, ['init', '-q', '--bare', '-b', 'main', bare]);
    const work = path.join(root, 'work'); fs.mkdirSync(work);
    const commit = (directory, message) => {git(directory, ['add', '.']); git(directory, ['commit', '-qm', message]);};
    const identify = directory => {git(directory, ['config', 'user.name', 'Fixture']); git(directory, ['config', 'user.email', 'fixture@example.invalid']);};
    git(work, ['init', '-q', '-b', 'main']); identify(work);
    git(work, ['remote', 'add', 'origin', GITHUB]);
    // The real transport, served from the bare repository: git runs this in place of ssh to github.com.
    const ssh = path.join(root, 'ssh'); fs.writeFileSync(ssh, `#!/bin/sh\nfor last; do :; done\ncommand=$(printf '%s' "$last" | sed -e 's#^git-#git #' -e "s#example/local-fixture.git#${bare}#")\nexec sh -c "$command"\n`, {mode: 0o755});
    process.env.GIT_SSH_COMMAND = ssh;
    fs.mkdirSync(path.join(work, 'src'));
    const write = (directory, name, text) => {fs.mkdirSync(path.dirname(path.join(directory, name)), {recursive: true}); fs.writeFileSync(path.join(directory, name), text);};
    write(work, 'README.md', 'Handle an accepted request and reject missing input.\n');
    write(work, 'AGENTS.md', 'Preserve purpose and meaningful tests.\n');
    write(work, '.gitignore', 'coverage.json\n');
    write(work, '.clouseau-local.json', JSON.stringify({version: 1, base_branch: 'main', readme: 'README.md', repository_policy: 'AGENTS.md',
      verification: [['node', '--version']], coverage: {format: 'istanbul', report: 'coverage.json', source_directory: 'src'}}));
    write(work, 'src/handler.js', handler('Boolean(input)', 'base'));
    write(work, 'src/unrelated.js', 'module.exports = 0;\n');
    if (ciConfig) write(work, '.github/clouseau.json', JSON.stringify(ciConfig));
    for (const [name, text] of Object.entries(files)) write(work, name, text);
    commit(work, 'feat: accept input'); git(work, ['push', '-q', 'origin', 'main']);
    git(work, ['checkout', '-q', '-b', 'feature']);
    write(work, 'src/handler.js', handler('{ if (!input) throw Error("Missing input"); return true; }', 'base'));
    write(work, 'src/new.js', 'module.exports = 1;\n');
    commit(work, 'fix: reject missing input'); git(work, ['push', '-q', 'origin', 'feature']);
    const other = path.join(root, 'other'); git(root, ['clone', '-q', bare, other]); identify(other);
    const advance = (name, text, message = 'chore: move main') => {
      write(other, name, text); commit(other, message); git(other, ['push', '-q', 'origin', 'main']);
      return git(other, ['rev-parse', 'HEAD']).trim();
    };
    const head = () => git(work, ['rev-parse', 'HEAD']).trim();
    const remoteHead = () => git(bare, ['rev-parse', 'refs/heads/feature']).trim();
    const pull = {state: 'open', base: 'main', head: head(), ref: 'feature', repository: 'example/local-fixture', body: 'Body.\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)'};
    const events = [];
    const execute = (program, args, options) => {
      assert.equal(program, 'gh');
      if (args.includes('PATCH')) {
        pull.body = JSON.parse(options.input).body;
        events.push(`patch:${remoteHead() === pull.head ? 'before-push' : 'after-push'}`);
        return '';
      }
      events.push('read');
      return JSON.stringify(pull);
    };
    return await run({root, bare, work, other, advance, head, remoteHead, pull, events, execute, commit, write});
  } finally {delete process.env.GIT_SSH_COMMAND; fs.rmSync(root, {recursive: true, force: true});}
}

const request = (root, text = 'Reject missing input.') => {
  const filename = path.join(root, 'requirement.txt'); fs.writeFileSync(filename, text); return filename;
};
const stub = (extra = {}) => {
  const seen = {reviews: [], publishes: []};
  return {seen, review: async args => {seen.reviews.push(args); return extra.result || {decision: 'auto_approve', receipt: '/receipt.json', head_sha: seen.reviews.length ? extra.head() : null};},
    publish: async args => {seen.publishes.push(args); return {marker: MARKER('1'.repeat(40)), artifact_commit: '1'.repeat(40)};}};
};
const args = (f, extra = {}) => ({pr: '7', directory: f.work, 'request-file': request(f.root), harness: 'claude', ...extra});
const unchanged = (f, before) => {assert.equal(f.head(), before); assert.equal(git(f.work, ['status', '--porcelain']), '');};

test('the pull request body keeps exactly one marker: replaced where it was, appended when absent', () => {
  const next = MARKER('2'.repeat(40));
  assert.equal(withMarker('', next), `${next}\n`);
  assert.equal(withMarker('Body.\n\n', next), `Body.\n\n${next}\n`);
  assert.equal(withMarker(`Body.\n${MARKER('1'.repeat(40))}\nTail`, next), `Body.\n${next}\nTail`);
  assert.equal(withMarker(`${MARKER('1'.repeat(40))} and ${MARKER('3'.repeat(40))} end`, next), `${next}  and  end`.replace('  and  end', ' and  end'));
});

test('refresh refuses before it changes anything: arguments, harness, dirty worktree, pull request facts, head, conflicts', async () => {
  await pullRepository(async f => {
    const before = f.head(); const dependencies = {...stub(), execute: f.execute, available: () => true};
    const refuses = (given, pattern, dependency = dependencies) => assert.rejects(refreshPull(given, dependency), pattern);
    await refuses({...args(f), pr: 'x'}, /pull request number/);
    await refuses({...args(f), pr: undefined}, /pull request number/);
    await refuses({...args(f), 'request-file': undefined}, /requirement file/);
    await refuses({...args(f), harness: undefined}, /exactly one of --agent/);
    await refuses({...args(f), agent: 'claude'}, /exactly one of --agent/);
    await refuses({...args(f), harness: undefined, agent: 'nope'}, /Supported agent harnesses/);
    await refuses({...args(f), harness: 'nope'}, /Unsupported --harness/);
    await refuses(args(f), /claude harness is not installed/, {...dependencies, available: () => false});
    fs.writeFileSync(path.join(f.work, 'untracked.txt'), 'x');
    await refuses(args(f), /uncommitted or untracked/);
    fs.rmSync(path.join(f.work, 'untracked.txt'));
    for (const [change, pattern] of [[{state: 'closed'}, /not open/], [{repository: 'someone/fork'}, /comes from someone\/fork/],
      [{ref: 'other-branch'}, /not the pull request branch other-branch/], [{base: 'release'}, /against release, not the configured base main/],
      [{head: 'f'.repeat(40)}, /is not the head of pull request 7/]]) {
      const original = {...f.pull}; Object.assign(f.pull, change);
      await refuses(args(f), pattern); Object.assign(f.pull, original);
    }
    // A detached head is not the pull request branch.
    git(f.work, ['checkout', '-q', '--detach']);
    await refuses(args(f), /not the pull request branch feature/);
    git(f.work, ['checkout', '-q', 'feature']);
    // A head that is a merge, but not of this pull request head and the base, is not resumable either.
    git(f.work, ['commit', '-q', '--allow-empty', '-m', 'chore: local only']);
    await refuses(args(f), /is not the head of pull request 7/);
    git(f.work, ['reset', '-q', '--hard', before]);
    assert.deepEqual(dependencies.seen.reviews, []);
    unchanged(f, before);
  });
});

test('refresh leaves the checkout alone on a conflict, an unrelated base and a refused merge, and does nothing when the base is already merged', async () => {
  await pullRepository(async f => {
    const before = f.head(); const dependencies = {...stub(), execute: f.execute, available: () => true};
    assert.equal((await refreshPull(args(f), dependencies)).status, 'up_to_date');
    const cwd = process.cwd(); process.chdir(f.work);
    try {assert.equal((await refreshPull(args(f, {directory: undefined}), dependencies)).status, 'up_to_date', 'the checkout defaults to the current directory');}
    finally {process.chdir(cwd);}
    f.advance('src/handler.js', 'module.exports = "main";\n');
    await assert.rejects(refreshPull(args(f), dependencies), error => {
      assert.match(error.message, /origin\/main cannot be merged cleanly \(conflicts in src\/handler\.js\)\. Nothing was changed/);
      return true;
    });
    unchanged(f, before);
    assert.ok(!fs.existsSync(path.join(f.work, '.git/MERGE_HEAD')));
    // A history unrelated to the pull request's cannot be merged cleanly either, and git's own reason is shown.
    git(f.other, ['checkout', '-q', '--orphan', 'fresh']); git(f.other, ['rm', '-rfq', '.']);
    f.write(f.other, 'README.md', 'unrelated\n'); f.commit(f.other, 'chore: unrelated root');
    git(f.other, ['push', '-q', '-f', 'origin', 'fresh:main']);
    await assert.rejects(refreshPull(args(f), dependencies), /origin\/main cannot be merged cleanly \(.*unrelated histories/);
    unchanged(f, before);
    assert.deepEqual(dependencies.seen.reviews, []);
  });
});

test('a refused merge (a hook) is aborted and reported without a half-made merge', async () => {
  await pullRepository(async f => {
    const before = f.head(); const dependencies = {...stub(), execute: f.execute, available: () => true};
    f.advance('docs.md', 'moved\n');
    const hook = path.join(f.work, '.git/hooks/pre-merge-commit');
    fs.writeFileSync(hook, '#!/bin/sh\necho refused-by-hook >&2\nexit 1\n', {mode: 0o755});
    await assert.rejects(refreshPull(args(f), dependencies), /Merging origin\/main failed \(.*\); the branch is unchanged and nothing was pushed/);
    unchanged(f, before);
    assert.ok(!fs.existsSync(path.join(f.work, '.git/MERGE_HEAD')));
  });
});

test('a refresh merges the base (never a rebase), reviews the merge commit, and pushes once after the marker is in the body', async () => {
  await pullRepository(async f => {
    const before = f.head();
    const moved = f.advance('docs.md', 'moved\n');
    const dependencies = {...stub({head: () => f.head()}), execute: f.execute, available: () => true};
    const result = await refreshPull(args(f), dependencies);
    assert.equal(result.status, 'refreshed'); assert.equal(result.pushed, true); assert.equal(result.previous_head_sha, before);
    const merged = f.head();
    assert.notEqual(merged, before);
    assert.deepEqual(git(f.work, ['rev-list', '--parents', '-n', '1', 'HEAD']).trim().split(' ').slice(1), [before, moved], 'a merge of the old head and the base tip');
    assert.equal(git(f.work, ['log', '-1', '--format=%s']).trim(), 'Merge origin/main into feature');
    assert.equal(f.remoteHead(), merged, 'pushed once, as a fast-forward');
    assert.equal(dependencies.seen.reviews.length, 1);
    assert.equal(dependencies.seen.reviews[0].base, 'origin/main'); assert.equal(dependencies.seen.reviews[0].harness, 'claude');
    assert.deepEqual(dependencies.seen.publishes, [{directory: f.work, receipt: '/receipt.json'}]);
    assert.equal(result.warnings, undefined);
    assert.ok(f.pull.body.includes(MARKER('1'.repeat(40))) && f.pull.body.includes('Generated with'), 'the marker joins the existing body');
    assert.deepEqual(f.events.filter(event => event.startsWith('patch')), ['patch:before-push']);
    assert.equal(git(f.work, ['status', '--porcelain']), '');
  });
});

test('publication warnings (protected controls changed) reach the result', async () => {
  await pullRepository(async f => {
    f.advance('docs.md', 'moved\n');
    const dependencies = {...stub({head: () => f.head()}), execute: f.execute, available: () => true};
    const publish = dependencies.publish;
    dependencies.publish = async given => ({...await publish(given), warnings: ['Protected review controls changed (x)']});
    assert.deepEqual((await refreshPull(args(f), dependencies)).warnings, ['Protected review controls changed (x)']);
  });
});

test('a review that does not pass, awaits an agent or fails never pushes; neither does a pass without a receipt', async () => {
  await pullRepository(async f => {
    const before = f.head(); const moved = f.advance('docs.md', 'moved\n');
    const run = async (result, extra = {}) => refreshPull(args(f, extra), {...stub({result}), execute: f.execute, available: () => true});
    const held = await run({decision: 'repair_required', receipt: null});
    assert.equal(held.pushed, false); assert.equal(held.decision, 'repair_required'); assert.match(held.note, /merge commit remains in the local branch/);
    assert.equal(f.remoteHead(), before); assert.equal(f.pull.body.includes('clouseau-local-review'), false);
    const merged = f.head();
    // The interrupted refresh resumes on its own merge commit: no second merge, no new fetch of the base.
    f.advance('docs2.md', 'moved again\n');
    const awaiting = await run({status: 'awaiting_agent', request_file: 'r', then: 'old'}, {harness: undefined, agent: 'claude'});
    assert.equal(awaiting.pushed, false); assert.match(awaiting.then, /Repeat the identical refresh command/);
    assert.equal(f.head(), merged, 'resuming does not merge again');
    const failed = await run({status: 'failed', reason: 'source_not_found', path: 'x'});
    assert.equal(failed.status, 'failed'); assert.equal(failed.pushed, false);
    await assert.rejects(run({decision: 'auto_approve', receipt: null}), /produced no signed receipt.*nothing was pushed/);
    assert.equal(f.remoteHead(), before); assert.equal(f.head(), merged); assert.equal(moved.length, 40);
  });
});

test('a pass is not pushed when the checkout, the pull request or the push itself changed underneath it', async () => {
  const scenarios = [
    ['the checkout', f => f.write(f.work, 'late.txt', 'x'), /Local source changed during review/],
    ['a closed pull request', f => {f.pull.state = 'closed';}, /changed during the refresh \(head .*\); nothing was pushed/],
    ['a moved pull request head', f => {f.pull.head = 'c'.repeat(40);}, /changed during the refresh \(head c+, expected [0-9a-f]{40}\); nothing was pushed/],
  ];
  for (const [name, mutate, pattern] of scenarios) {
    await pullRepository(async f => {
      const before = f.head(); f.advance('docs.md', 'moved\n');
      const dependencies = {...stub(), execute: f.execute, available: () => true,
        review: async () => {mutate(f); return {decision: 'auto_approve', receipt: '/receipt.json', head_sha: git(f.work, ['rev-parse', 'HEAD']).trim()};}};
      await assert.rejects(refreshPull(args(f), dependencies), pattern, name);
      assert.equal(f.remoteHead(), before, `${name}: nothing was pushed`);
      assert.deepEqual(f.events.filter(event => event.startsWith('patch')), [], `${name}: the body was not edited`);
    });
  }
  // The branch moved on GitHub (a non-fast-forward push): the body edit is undone and the failure says so.
  await pullRepository(async f => {
    f.advance('docs.md', 'moved\n');
    const theirs = path.join(f.root, 'theirs'); git(f.root, ['clone', '-q', f.bare, theirs]);
    git(theirs, ['config', 'user.name', 'T']); git(theirs, ['config', 'user.email', 't@example.invalid']);
    git(theirs, ['checkout', '-q', 'feature']); f.write(theirs, 'theirs.txt', 'x'); f.commit(theirs, 'chore: someone else pushed');
    git(theirs, ['push', '-q', 'origin', 'feature']);
    const pushed = git(f.bare, ['rev-parse', 'refs/heads/feature']).trim();
    const original = f.pull.body;
    await assert.rejects(refreshPull(args(f), {...stub({head: () => f.head()}), execute: f.execute, available: () => true}),
      /The push failed \(.*\); the pull request body was restored and the branch on GitHub is unchanged/);
    assert.equal(f.pull.body, original); assert.equal(f.remoteHead(), pushed);
    assert.equal(f.events.filter(event => event.startsWith('patch')).length, 2, 'the body was edited, then restored');
  });
});

// A signed fixture: an enrolled identity, the protected configuration that trusts it, and a runtime with a counting reviewer.
function signedFixture(t, localReview = {}) {
  const state = fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-refresh-state-'));
  t.after(() => fs.rmSync(state, {recursive: true, force: true}));
  const identity = initializeIdentity(state, 'fixture-author');
  const config = {...require('../test/fixtures/config.json'), version: 2, repository_policy: 'AGENTS.md', readme: 'README.md',
    acceptance: {examiner: 'deepseek-flash', challenger: 'deepseek-v4-pro', grader: 'routed', grading_model: 'deepseek-flash', repair_attempts: 2},
    local_review: {mode: 'required', reviewer_digest: 'e'.repeat(64), max_age_seconds: 3600, keys: [identity.public_identity], ...localReview}};
  const calls = [];
  const runtime = f => ({state, ask: fakeHarness(calls), verify: () => ({fixture_execution_only: true}), installed, execute: f.execute, available: () => true});
  const refresh = (f, extra = {}) => main(['refresh', '--pr', '7', '--directory', f.work, '--request-file', extra.request || request(f.root), '--harness', 'claude'], runtime(f));
  return {state, config, calls, runtime, refresh};
}

test('through the command: identical evidence is not reviewed again, anything else is, and the signed receipt is published for the merged head', async t => {
  const {state, config, calls, runtime, refresh} = signedFixture(t);
  await pullRepository(async f => {
    const requestFile = request(f.root);
    // The earlier accepted review of the pull request head, as the author ran it.
    const first = await main(['review', '--directory', f.work, '--base', 'origin/main', '--request-file', requestFile, '--harness', 'claude'], runtime(f));
    assert.equal(first.decision, 'auto_approve'); assert.ok(first.receipt);
    const firstCalls = calls.length; assert.ok(firstCalls >= 2);
    assert.ok(fs.readdirSync(path.join(state, 'unit-reuse')).length >= 2, 'the accepted review left its answers');
    // The base moved elsewhere: the same evidence, new revision. Nothing is asked.
    f.advance('docs.md', 'moved\n');
    const before = f.head();
    const refreshed = await refresh(f, {request: requestFile});
    assert.equal(refreshed.status, 'refreshed'); assert.equal(refreshed.harness_invocations, 0); assert.ok(refreshed.reused_calls >= 2);
    assert.equal(calls.length, firstCalls, 'the reviewer was not asked'); assert.equal(f.remoteHead(), f.head()); assert.notEqual(f.head(), before);
    const receipt = JSON.parse(fs.readFileSync(refreshed.receipt)).payload;
    assert.equal(receipt.record.snapshot.head_sha, f.head()); assert.equal(receipt.record.snapshot.base_sha, git(f.work, ['rev-parse', 'origin/main']).trim());
    assert.ok(f.pull.body.includes(refreshed.marker)); assert.ok(git(f.bare, ['tag', '-l', 'clouseau-review/*']).includes(receipt.nonce));
    // Each kind of change invalidates: a base change to a file the pull request changed, to the contract, to the policy.
    for (const [name, text] of [['src/handler.js', handler('Boolean(input)', 'moved on main')], ['README.md', 'A changed contract.\n'], ['AGENTS.md', 'A changed policy.\n']]) {
      f.pull.head = f.head();
      f.advance(name, text, `chore: change ${name}`);
      const asked = calls.length;
      const changed = await refresh(f, {request: requestFile});
      assert.equal(changed.status, 'refreshed', name); assert.ok(calls.length > asked, `${name}: the reviewer is asked again`);
      assert.equal(changed.reused_calls, 0, name); f.pull.head = f.head();
    }
    // A pull request commit invalidates it, and so does a different requirement.
    f.pull.head = f.head(); f.write(f.work, 'src/new.js', 'module.exports = 2;\n'); f.commit(f.work, 'fix: change the pull request itself');
    f.pull.head = f.head(); f.advance('docs.md', 'moved again\n');
    let asked = calls.length;
    assert.equal((await refresh(f, {request: requestFile})).reused_calls, 0); assert.ok(calls.length > asked);
    f.pull.head = f.head(); f.advance('docs.md', 'moved a third time\n');
    asked = calls.length;
    const reworded = await refresh(f, {request: request(f.root, 'A different requirement.')});
    assert.equal(reworded.reused_calls, 0); assert.ok(calls.length > asked);
    // Unmodified evidence under the new requirement now matches the last accepted review of exactly that input.
    f.pull.head = f.head(); f.advance('docs.md', 'moved a fourth time\n');
    asked = calls.length;
    assert.ok((await refresh(f, {request: request(f.root, 'A different requirement.')})).reused_calls >= 2); assert.equal(calls.length, asked);
  }, {ciConfig: config});
});

test('through the command, a chunked review reuses every unit, integration pass and grading round while nothing it saw has changed', async t => {
  const {state, config, calls, runtime, refresh} = signedFixture(t, {chunked: {force: true, params: {C: 1000, S: 20000}}});
  await pullRepository(async f => {
    const requestFile = request(f.root);
    const first = await main(['review', '--directory', f.work, '--base', 'origin/main', '--request-file', requestFile, '--harness', 'claude'], runtime(f));
    assert.equal(first.decision, 'auto_approve');
    const plan = JSON.parse(fs.readFileSync(first.record, 'utf8'));
    assert.equal(plan.version, 3); assert.ok(plan.partition.units.length >= 2, 'the change is reviewed in more than one unit');
    const firstCalls = calls.length; assert.ok(firstCalls >= 4);
    f.advance('docs.md', 'moved\n');
    const refreshed = await refresh(f, {request: requestFile});
    assert.equal(refreshed.status, 'refreshed'); assert.equal(refreshed.harness_invocations, 0); assert.equal(refreshed.reused_calls, firstCalls);
    assert.equal(calls.length, firstCalls, 'no unit was asked again');
    const record = JSON.parse(fs.readFileSync(refreshed.record, 'utf8'));
    assert.equal(record.version, 3); assert.equal(record.snapshot.head_sha, f.head());
    // The base changed a file the pull request changed: the change manifest every unit sees moved, so every unit is asked again.
    f.pull.head = f.head(); f.advance('src/handler.js', handler('Boolean(input)', 'moved on main'));
    const changed = await refresh(f, {request: requestFile});
    assert.equal(changed.reused_calls, 0); assert.ok(calls.length > firstCalls);
  }, {ciConfig: config});
});

'use strict';

// Evidence-keyed reuse of reviewer answers (docs/local-review.md, "Refreshing a pull request after its base moved").
//
// A local review asks a harness one question at a time: every unit investigation, every integration pass and every
// grading round is a `task` whose prompt is the complete evidence the reviewer sees. This module remembers the answer of
// every call of a review that was ACCEPTED (`auto_approve`) under a key made of that prompt, and can hand the answer back
// to a later review whose prompt is the same. It decides nothing: a reused answer goes through the very check a fresh one
// goes through, against the new snapshot, and a call whose key is not in the store is asked as before.
//
// The key is strict. It covers the policy and stage text, the schema, the role and phase, the whole evidence (every
// changed patch, every base and head source, every linked source, the seams, the requirement, the prior findings and the
// change manifest) and the review semantics of the engine. The only values left out are the ones that name the revision
// rather than describe it, and they are replaced by placeholders so that two runs compare equal exactly when everything
// else is byte-identical:
//   - the base and head commit ids, and the snapshot and unit-view digests (they hash the very values compared); the
//     commit ids of a file's recent history are not replaced and still compare byte for byte;
//   - the subject of the head commit (the merge commit that a refresh creates replaces it; the requirement stays);
//   - for a verification command that passed (exit 0, no error, no signal): its output tails and output digests. Its
//     argv, exit code, coverage counters and configuration digest stay in the key, as does every byte of a failed one.

const fs = require('node:fs');
const path = require('node:path');
const {digest} = require('./acceptance.cjs');

const VERSION = 1;
const PREFIX = '<<clouseau-reuse:';
const token = name => `${PREFIX}${name}>>`;

const isCommand = value => value !== null && typeof value === 'object' && Array.isArray(value.argv);
const passed = command => command.exit_code === 0 && !command.error && !command.signal;

// The recorded verification, without the parts of a passing command that only describe how long it took to say so.
function neutralVerification(content) {
  const record = JSON.parse(content);
  const commands = record.commands?.map(command => {
    if (!isCommand(command) || !passed(command)) return command;
    const {stdout, stderr, stdout_bytes, stderr_bytes, stdout_digest, stderr_digest, ...rest} = command;
    return rest;
  });
  const reports = record.coverage_reports?.map(({report_digest, ...rest}) => rest);
  const {report_digest, ...rest} = record;
  return JSON.stringify({...rest, commands, ...(reports ? {coverage_reports: reports} : {})});
}

function neutral(value) {
  if (Array.isArray(value)) return value.map(neutral);
  if (value === null || typeof value !== 'object') return value;
  const copy = Object.fromEntries(Object.entries(value).map(([key, item]) => [key, neutral(item)]));
  if (copy.kind === 'verification' && typeof copy.content === 'string') copy.content = neutralVerification(copy.content);
  // Commit ids in a file's recent history are not the base or the head, even when one of them is the commit the base now
  // points at: they stay as they are, and are compared as a whole, instead of being replaced by a revision placeholder.
  if (Array.isArray(copy.history)) copy.history = copy.history.map(entry => ({...entry, commits: digest(entry.commits)}));
  if (copy.claims !== null && typeof copy.claims === 'object' && 'title' in copy.claims) copy.claims = {...copy.claims, title: null};
  return copy;
}

// `subs` is [[literal, token]]: the values of this run that name its revision.
const replace = (text, subs, from, to) => subs.reduce((out, sub) => out.split(sub[from]).join(sub[to]), text);

// The key of a task, or null when the task cannot be keyed safely (its prompt is not the documented shape, or the
// text already contains a placeholder, which would let two different prompts collide).
function keyOf(task, {subs, semantics}) {
  const cut = task.prompt.lastIndexOf('\n');
  let packet;
  try {
    packet = neutral(JSON.parse(task.prompt.slice(cut + 1)));
  } catch {
    return null;
  }
  const raw = JSON.stringify({role: task.role, phase: task.phase, schema: task.schema, text: task.prompt.slice(0, cut), packet});
  if (raw.includes(PREFIX)) return null;
  return digest({version: VERSION, semantics, body: replace(raw, subs, 0, 1)});
}

// `literals()` gives the values of this run when a call is made: the digest of a snapshot changes when a source request
// adds evidence, so it is read per call. `read` turns reuse on; recording happens either way.
function createReuse({directory, read = false, semantics, literals}) {
  const pending = new Map();
  const stats = {reused: 0};
  const subsOf = () => {
    const {base, head, digests} = literals();
    return [[base, token('base')], [head, token('head')], ...digests.map((value, index) => [value, token(`digest-${index}`)])];
  };
  const file = key => path.join(directory, `${key}.json`);

  const load = (key, subs) => {
    try {
      const stored = JSON.parse(fs.readFileSync(file(key), 'utf8'));
      if (stored.version !== VERSION || stored.key !== key) return null;
      return JSON.parse(replace(stored.response, subs, 1, 0));
    } catch {
      return null;
    }
  };

  const wrap = ask => async task => {
    const subs = subsOf();
    const key = keyOf(task, {subs, semantics});
    if (key !== null && read) {
      const hit = load(key, subs);
      if (hit !== null) {
        try {
          task.check?.(hit.value);
          stats.reused++;
          return hit;
        } catch {
          // An answer that no longer validates against the new snapshot is not used; the reviewer is asked again.
        }
      }
    }
    const response = await ask(task);
    const text = JSON.stringify(response);
    if (key !== null && !text.includes(PREFIX)) pending.set(key, replace(text, subs, 0, 1));
    return response;
  };

  // Only an accepted review leaves answers behind.
  const commit = decision => {
    if (decision !== 'auto_approve' || !pending.size) return 0;
    fs.mkdirSync(directory, {recursive: true, mode: 0o700});
    for (const [key, response] of pending) fs.writeFileSync(file(key), JSON.stringify({version: VERSION, key, response}), {mode: 0o600});
    return pending.size;
  };

  return {wrap, commit, stats};
}

module.exports = {createReuse, keyOf, neutral, PREFIX};

'use strict';
const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {createReuse, keyOf, neutral, PREFIX} = require('./review-reuse.cjs');

const BASE = 'b'.repeat(40); const HEAD = 'a'.repeat(40); const DIGEST = 'd'.repeat(64);
const subsOf = ({base = BASE, head = HEAD, digest = DIGEST} = {}) => [[base, '<<clouseau-reuse:base>>'], [head, '<<clouseau-reuse:head>>'], [digest, '<<clouseau-reuse:digest-0>>']];
const verification = commands => JSON.stringify({commands, report_digest: 'f'.repeat(64), coverage: {status: 'exact'},
  coverage_reports: [{report: 'x.json', report_digest: 'e'.repeat(64), exact_coverage: {lines: [1, 1]}}]});
const packetOf = ({base = BASE, head = HEAD, digest = DIGEST, body = 'export const a = 1;\n', title = 'feat: a', commands} = {}) => ({
  review_context: {stage: 'local_pre_pr'},
  evidence: {digest, base_sha: base, head_sha: head, claims: {title, description: 'Reject missing input.'}, partition_of: digest,
    sources: {[`${head}:src/a.js`]: {path: 'src/a.js', ref: head, kind: 'source', content: body},
      verification: {kind: 'verification', ref: head, content: verification(commands || [{argv: ['npm', 'test'], exit_code: 0, stdout: 'ok in 12ms', stderr: '', stdout_digest: '1'.repeat(64), stderr_digest: '2'.repeat(64)}])}}}});
const taskOf = (packet, extra = {}) => ({role: 'examiner', phase: 'investigation', schema: {type: 'object', enum: [DIGEST]}, prompt: `Policy text.\n${JSON.stringify(packet)}`, ...extra});
const keyFor = (task, options = {}) => keyOf(task, {subs: subsOf(options.run), semantics: options.semantics || 's'.repeat(64)});

test('the key names the evidence, not the revision: ids, digests, the head subject and passing output do not change it', () => {
  const original = keyFor(taskOf(packetOf()));
  assert.match(original, /^[a-f0-9]{64}$/);
  const moved = {base: 'c'.repeat(40), head: '9'.repeat(40), digest: '8'.repeat(64)};
  const next = taskOf(packetOf({...moved, title: 'Merge origin/main into feature',
    commands: [{argv: ['npm', 'test'], exit_code: 0, stdout: 'ok in 99ms', stderr: 'warn', stdout_digest: '3'.repeat(64), stderr_digest: '4'.repeat(64)}]}));
  next.schema = {type: 'object', enum: [moved.digest]};
  assert.equal(keyFor(next, {run: moved}), original);
});

test('every other byte of the evidence is part of the key: sources, patches, request, policy text, schema, role, phase, engine semantics', () => {
  const original = keyFor(taskOf(packetOf()));
  const differs = (task, options) => assert.notEqual(keyFor(task, options), original);
  differs(taskOf(packetOf({body: 'export const a = 2;\n'})));
  differs(taskOf({...packetOf(), evidence: {...packetOf().evidence, claims: {title: 'feat: a', description: 'A different request.'}}}));
  differs({...taskOf(packetOf()), prompt: `Other policy.\n${JSON.stringify(packetOf())}`});
  differs(taskOf(packetOf(), {role: 'challenger'}));
  differs(taskOf(packetOf(), {phase: 'grading'}));
  differs(taskOf(packetOf(), {schema: {type: 'string'}}));
  differs(taskOf(packetOf()), {semantics: 't'.repeat(64)});
  // A failed command keeps every byte (its diagnosis is evidence); so does a passing command's argv and exit code.
  const failing = commands => taskOf(packetOf({commands}));
  const failedA = failing([{argv: ['npm', 'test'], exit_code: 1, stdout: 'boom', stderr: 'a'}]);
  const failedB = failing([{argv: ['npm', 'test'], exit_code: 1, stdout: 'boom', stderr: 'b'}]);
  assert.notEqual(keyFor(failedA), keyFor(failedB));
  assert.notEqual(keyFor(failing([{argv: ['npm', 'run', 'x'], exit_code: 0}])), keyFor(failing([{argv: ['npm', 'test'], exit_code: 0}])));
  assert.notEqual(keyFor(failing([{argv: ['npm', 'test'], exit_code: 0, error: {code: 'E'}}])), keyFor(failing([{argv: ['npm', 'test'], exit_code: 0, error: {code: 'F'}}])));
  assert.notEqual(keyFor(failing([{argv: ['npm', 'test'], exit_code: 0, signal: 'SIGTERM'}])), keyFor(failing([{argv: ['npm', 'test'], exit_code: 0}])));
});

test('the recent history of a file compares by its own commit ids, even when the base tip is one of them', () => {
  const withHistory = (base, commits) => {
    const packet = packetOf({base, head: HEAD});
    packet.evidence.history = [{path: 'src/a.js', commits}];
    return taskOf(packet);
  };
  const tip = 'c'.repeat(40); const old = '5'.repeat(40);
  // Run 1: the base tip touched the file. Run 2: the base moved on and the same commit is now merely history.
  const first = keyOf(withHistory(old, `${old} feat: a`), {subs: subsOf({base: old}), semantics: 's'});
  const second = keyOf(withHistory(tip, `${old} feat: a`), {subs: subsOf({base: tip}), semantics: 's'});
  assert.equal(second, first);
  assert.notEqual(keyOf(withHistory(tip, `${tip} feat: a`), {subs: subsOf({base: tip}), semantics: 's'}), first, 'another commit in the history is another input');
});

test('a task that cannot be keyed safely has no key', () => {
  assert.equal(keyFor({role: 'examiner', phase: 'investigation', schema: {}, prompt: 'no packet here'}), null);
  assert.equal(keyFor({role: 'examiner', phase: 'investigation', schema: {}, prompt: '{"unterminated'}), null);
  assert.equal(keyFor(taskOf(packetOf({body: `a ${PREFIX}base>> b`}))), null, 'text that already holds a placeholder could collide');
});

test('neutral leaves non-verification data and a verification without commands alone, and survives a record that is not a command list', () => {
  assert.deepEqual(neutral([1, null, 'x']), [1, null, 'x']);
  assert.deepEqual(neutral({kind: 'source', content: 'x', claims: {description: 'no title here'}}), {kind: 'source', content: 'x', claims: {description: 'no title here'}});
  assert.equal(neutral({kind: 'verification', content: '{"fixture_execution_only":true}'}).content, '{"fixture_execution_only":true}');
  const odd = neutral({kind: 'verification', content: JSON.stringify({commands: ['not-a-command', null], coverage: {status: 'exact'}})});
  assert.deepEqual(JSON.parse(odd.content).commands, ['not-a-command', null]);
  assert.throws(() => neutral({kind: 'verification', content: 'not json'}));
  assert.equal(neutral({kind: 'verification', content: 12}).content, 12);
});

function store() {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-reuse-'));
  return {directory: path.join(directory, 'unit-reuse'), cleanup: () => fs.rmSync(directory, {recursive: true, force: true})};
}
const answer = (value = {kind: 'report'}) => ({value, provenance: {session: 's', request_digest: '7'.repeat(64)}});
const options = (directory, extra = {}) => ({directory, semantics: 's'.repeat(64), literals: () => ({base: BASE, head: HEAD, digests: [DIGEST]}), ...extra});

test('only an accepted review leaves answers, and only a reading review takes them', async () => {
  const s = store();
  try {
    const task = taskOf(packetOf());
    let asked = 0;
    const ask = async () => {asked++; return answer({kind: 'report', snapshot: DIGEST, head: HEAD});};
    // Not accepted: nothing is written, not even the directory.
    const rejected = createReuse(options(s.directory));
    await rejected.wrap(ask)(task);
    assert.equal(rejected.commit('repair_required'), 0);
    assert.equal(fs.existsSync(s.directory), false);
    // Nothing to write is not a write either.
    assert.equal(createReuse(options(s.directory)).commit('auto_approve'), 0);
    assert.equal(fs.existsSync(s.directory), false);
    // Accepted: recorded, but a recording-only review still asks.
    const writer = createReuse(options(s.directory));
    await writer.wrap(ask)(task);
    assert.equal(writer.commit('auto_approve'), 1);
    assert.equal(fs.statSync(s.directory).mode & 0o777, 0o700);
    const [file] = fs.readdirSync(s.directory);
    assert.equal(fs.statSync(path.join(s.directory, file)).mode & 0o777, 0o600);
    const stored = fs.readFileSync(path.join(s.directory, file), 'utf8');
    assert.ok(!stored.includes(HEAD) && !stored.includes(DIGEST), 'revision values are stored as placeholders');
    const passive = createReuse(options(s.directory));
    await passive.wrap(ask)(task);
    assert.equal(asked, 3); assert.equal(passive.stats.reused, 0);
    // A reading review on a moved revision takes the answer and puts the new revision values into it.
    const moved = {base: 'c'.repeat(40), head: '9'.repeat(40), digest: '8'.repeat(64)};
    const reader = createReuse(options(s.directory, {read: true, literals: () => ({base: moved.base, head: moved.head, digests: [moved.digest]})}));
    const next = taskOf(packetOf(moved), {schema: {type: 'object', enum: [moved.digest]}});
    let checked = 0;
    const hit = await reader.wrap(ask)({...next, check: value => {checked++; assert.equal(value.snapshot, moved.digest);}});
    assert.equal(asked, 3, 'the reviewer was not asked'); assert.equal(checked, 1); assert.equal(reader.stats.reused, 1);
    assert.deepEqual(hit.value, {kind: 'report', snapshot: moved.digest, head: moved.head});
    assert.deepEqual(hit.provenance, answer().provenance);
    // Changed evidence is a miss; so is a task with no check (a grading call) that finds nothing.
    await reader.wrap(ask)(taskOf(packetOf({...moved, body: 'changed'}), {schema: {type: 'object', enum: [moved.digest]}}));
    assert.equal(asked, 4);
    // A grading call has no check and takes its answer as is.
    const grading = taskOf(packetOf(), {phase: 'grading'});
    const writing = createReuse(options(s.directory));
    await writing.wrap(ask)(grading); writing.commit('auto_approve');
    const reading = createReuse(options(s.directory, {read: true}));
    await reading.wrap(ask)(grading);
    assert.equal(asked, 5); assert.equal(reading.stats.reused, 1);
  } finally {s.cleanup();}
});

test('a stored answer that no longer validates, is damaged, is another version or another key is not used', async () => {
  const s = store();
  try {
    const task = taskOf(packetOf());
    let asked = 0;
    const ask = async () => {asked++; return answer();};
    const writer = createReuse(options(s.directory));
    await writer.wrap(ask)(task); writer.commit('auto_approve');
    const [name] = fs.readdirSync(s.directory); const file = path.join(s.directory, name);
    const good = fs.readFileSync(file, 'utf8');
    const run = async check => {
      const reader = createReuse(options(s.directory, {read: true}));
      await reader.wrap(ask)({...task, check});
      return reader.stats.reused;
    };
    assert.equal(await run(() => {throw new Error('invalid under the new snapshot');}), 0); assert.equal(asked, 2);
    for (const damaged of ['not json', JSON.stringify({...JSON.parse(good), version: 2}), JSON.stringify({...JSON.parse(good), key: 'x'.repeat(64)})]) {
      fs.writeFileSync(file, damaged);
      assert.equal(await run(undefined), 0);
    }
    assert.equal(asked, 5);
    fs.writeFileSync(file, good);
    assert.equal(await run(undefined), 1);
    // A task without a key is asked and never stored; an answer holding a placeholder is never stored.
    const unkeyed = createReuse(options(s.directory, {read: true}));
    await unkeyed.wrap(ask)({role: 'examiner', phase: 'investigation', schema: {}, prompt: 'plain'});
    const tricky = createReuse(options(s.directory, {read: true}));
    await tricky.wrap(async () => answer({note: `${PREFIX}head>>`}))(taskOf(packetOf({body: 'other'})));
    assert.equal(unkeyed.commit('auto_approve') + tricky.commit('auto_approve'), 0);
  } finally {s.cleanup();}
});

